import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { replay } from '@sibei/api';
import type { Operation } from '@sibei/api';
import { SCHEMA_VERSION, idsOf, migrateDocument, staffOf } from '@sibei/model';
import type { RawDocument, Score } from '@sibei/model';
import { toLegacyDocument } from '../fixtures/legacy-document.js';

/**
 * ADR-0041 slice 1 (SIB2-225): the document shape became parts > staves > voices, and nothing else may have changed.
 *
 * `tests/fixtures/model-v3/` was generated by the **pre-ADR-0041 build** (origin/main at 9cbed5e): `oplog.json` is a
 * 42-operation log as a v3 store held it (recorded ids, op payloads with no staff or voice), `score.json` the
 * document that build folded it to, and `import-*` the same pair for a single `score.import` carrying a whole v3
 * document, which is what `duplicate` and every import write. The tests prove (1) the migration is a pure
 * rearrangement, (2) an old log still replays to exactly the old result, and (3) an old `score.import` still replays.
 */

const dir = join(import.meta.dirname, '../fixtures/model-v3');
const read = <T>(name: string): T => JSON.parse(readFileSync(join(dir, name), 'utf8')) as T;

const OLD_DOCUMENT = (): RawDocument => read<RawDocument>('score.json');

describe('the v3 -> v4 migration (ADR-0028, ADR-0041)', () => {
  it('wraps each bar into one part, one staff, one voice and files chords and text in the harmony lane', () => {
    const result = migrateDocument(OLD_DOCUMENT());
    expect(result.migrated).toBe(true);
    expect(result.from).toBe(3);
    const score = result.score;
    expect(score.schemaVersion).toBe(SCHEMA_VERSION);
    expect(score.parts).toHaveLength(1);
    expect(score.parts[0]!.staves).toHaveLength(1);
    const staff = staffOf(score)!;
    expect(staff).toMatchObject({ id: 'staff-1', type: 'standard', clef: 'treble' });
    expect(staff.bars.map((b) => b.barId)).toEqual(score.bars.map((b) => b.id));
    expect(staff.bars.every((b) => b.voices.length === 1 && b.voices[0]!.index === 1)).toBe(true);
    expect(score.harmony.map((h) => h.barId)).toEqual(score.bars.map((b) => b.id));
    for (const bar of score.bars) expect(bar).not.toHaveProperty('items');
  });

  it('is a pure rearrangement: the legacy shape rebuilt from the result is the original document, byte for byte', () => {
    const { score } = migrateDocument(OLD_DOCUMENT());
    expect(JSON.stringify(toLegacyDocument(score))).toBe(JSON.stringify(OLD_DOCUMENT()));
  });

  it('keeps every id, and adds only the structural ones', () => {
    const old = OLD_DOCUMENT();
    const oldIds: string[] = [old.id as string];
    const walk = (value: unknown): void => {
      if (Array.isArray(value)) value.forEach(walk);
      else if (typeof value === 'object' && value !== null) {
        const record = value as Record<string, unknown>;
        if (typeof record.id === 'string') oldIds.push(record.id);
        Object.values(record).forEach(walk);
      }
    };
    walk(old.bars);
    walk(old.sections);
    walk(old.spanners);
    const { score } = migrateDocument(old);
    const newIds = new Set(idsOf(score));
    for (const id of oldIds) expect(newIds.has(id), id).toBe(true);
    expect([...newIds].filter((id) => !oldIds.includes(id)).sort()).toEqual(['part-1', 'staff-1']);
  });

  it('is deterministic, and a current document passes through untouched', () => {
    const once = migrateDocument(OLD_DOCUMENT()).score;
    expect(migrateDocument(OLD_DOCUMENT()).score).toEqual(once);
    const again = migrateDocument(JSON.parse(JSON.stringify(once)));
    expect(again.migrated).toBe(false);
    expect(again.score).toEqual(once);
  });
});

describe('an old operation log replays to the old result (ADR-0003, ADR-0028)', () => {
  it('replays the 42-operation v3 log, op payloads without staff or voice, to the document the old build stored', () => {
    const log = read<Operation[]>('oplog.json');
    const score = replay(log) as Score;
    expect(score.schemaVersion).toBe(SCHEMA_VERSION);
    expect(JSON.stringify(toLegacyDocument(score))).toBe(JSON.stringify(read('score.json')));
  });

  it('replays every prefix of the log, because undo is replay', () => {
    const log = read<Operation[]>('oplog.json');
    for (const n of [1, 10, 25, log.length - 1]) {
      const score = replay(log.slice(0, n)) as Score;
      expect(score.id).toBe('v3-chart');
      expect(idsOf(score).length).toBeGreaterThan(0);
    }
  });

  it('still replays a score.import whose payload carries a whole v3-shaped document', () => {
    const log = read<Operation[]>('import-oplog.json');
    const payload = (log[0] as { payload: { document: Score } }).payload.document;
    expect(payload.schemaVersion).toBe(3);
    expect(payload).not.toHaveProperty('parts');
    const score = replay(log) as Score;
    expect(score.schemaVersion).toBe(SCHEMA_VERSION);
    expect(JSON.stringify(toLegacyDocument(score))).toBe(JSON.stringify(read('import-score.json')));
  });
});
